package com.project7.localmanager;
import java.io.*;import java.lang.reflect.*;import java.nio.file.*;import java.util.*;import android.system.Os;
public final class StoryBasicsHost {
 static final byte[]EID=new byte[12];static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 static byte[]profile(){return BsonLite.document("account",BaiyeHost.ACCOUNT,"an",BaiyeHost.ACCOUNT,"money",90,"ending",Arrays.asList(7),"opaque","keep","std",BsonLite.document("dw",Arrays.asList(1,2),"dwh",14,"dwr",false,"opaque","story"));}
 static List<ProtoLite.EntityMessage>send(BaiyeHost.Disk d,String method,byte[]params)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();check(StoryBasicsGateway.handleDirect(d.g,out,EID,BaiyeGateway.digest(method),params,BaiyeHost.ACCOUNT,null,null),"handled");return BaiyeHost.frames(out.toByteArray());}
 static ProtoLite.EntityMessage get(List<ProtoLite.EntityMessage>r,String name){for(ProtoLite.EntityMessage m:r)if(Arrays.equals(m.methodMd5,BaiyeGateway.digest(name)))return m;throw new AssertionError(name);}
 public static void main(String[]args)throws Exception{
  android.content.Context c=new android.content.Context(new File(args[0]),new android.content.res.AssetManager(new File(args[0])));CoreDrawPolicy.prepare(c);HistoryDrawPolicy.prepare(c);SelectorPolicy.prepare(c);OfflineMechanismGateway.prepare(c);Map<String,Object>cases=new LinkedHashMap<>();try(BaiyeHost.Disk d=new BaiyeHost.Disk(new File(args[0]),profile())){
   Method stock=LocalGatewayServer.class.getDeclaredMethod("handleResourceRpc",OutputStream.class,byte[].class,byte[].class,byte[].class,String.class);stock.setAccessible(true);
   for(String m:new String[]{"getShareLink","readDailyWish"}){byte[]before=d.read();ByteArrayOutputStream out=new ByteArrayOutputStream();check(Boolean.FALSE.equals(stock.invoke(d.g,out,EID,BaiyeGateway.digest(m),BsonLite.EMPTY_DOCUMENT,BaiyeHost.ACCOUNT)),"original generic resource unhandled "+m);check(Arrays.equals(before,d.read())&&out.size()==0,"stock no side effects");}
   byte[]before=d.read();List<ProtoLite.EntityMessage>share=send(d,"getShareLink",BsonLite.document("e",7,"cg",Arrays.asList(281),"_cbid_",7));check("".equals(BsonLite.stringValue(get(share,"replyShareLink").parameters,"l")),"empty typed link");get(share,"showMessageStr");BaiyeHost.callback(share);check(Arrays.equals(before,d.read()),"share never mutates profile");cases.put("share",BsonLite.messagePackValue(get(share,"replyShareLink").parameters,false));
   int writes=Os.renames;List<ProtoLite.EntityMessage>read=send(d,"readDailyWish",BsonLite.document("_cbid_",7));BaiyeHost.callback(read);check(Os.renames==writes+1,"stock atomic writer once");byte[]expected=BsonLite.withProfileDocument(before,"std",BsonLite.withProfileBool(BsonLite.documentValue(before,"std"),"dwr",true));check(Arrays.equals(expected,d.read()),"exact only std.dwr delta");check(Boolean.TRUE.equals(BsonLite.boolValue(BsonLite.documentValue(d.read(),"std"),"dwr")),"disk persistent true");cases.put("read",BsonLite.messagePackValue(get(read,"syncDailyWish").parameters,false));
   send(d,"readDailyWish",BsonLite.EMPTY_DOCUMENT);check(Arrays.equals(expected,d.read()),"idempotent repeat");
  }
  try(BaiyeHost.Disk d=new BaiyeHost.Disk(new File(args[0]),profile())){byte[]before=d.read();Os.failBefore=true;List<ProtoLite.EntityMessage>r=send(d,"readDailyWish",BsonLite.EMPTY_DOCUMENT);get(r,"showMessageStr");check(Arrays.equals(before,d.read()),"precommit no false persisted success");Os.failAfter=true;r=send(d,"readDailyWish",BsonLite.EMPTY_DOCUMENT);get(r,"syncDailyWish");check(Boolean.TRUE.equals(BsonLite.boolValue(BsonLite.documentValue(d.read(),"std"),"dwr")),"postrename recognized commit");}
  try(BaiyeHost.Disk d=new BaiyeHost.Disk(new File(args[0]),profile())){byte[]before=d.read();send(d,"readDailyWish",BsonLite.document("surprise",1));for(Object invalid:new Object[]{"7",0,-1}){send(d,"readDailyWish",BsonLite.document("_cbid_",invalid));check(Arrays.equals(before,d.read()),"invalid callback rejected "+invalid);}for(byte type:new byte[]{1,18}){byte[]raw=java.nio.ByteBuffer.allocate(21).order(java.nio.ByteOrder.LITTLE_ENDIAN).putInt(21).put(type).put("_cbid_".getBytes("UTF-8")).put((byte)0).putLong(type==1?Double.doubleToLongBits(7.0):Long.MAX_VALUE).put((byte)0).array();send(d,"readDailyWish",raw);check(Arrays.equals(before,d.read()),"double/overflow callback rejected");}check(Arrays.equals(before,d.read()),"unknown args rejected");ByteArrayOutputStream out=new ByteArrayOutputStream();check(!StoryBasicsGateway.handleDirect(d.g,out,EID,BaiyeGateway.digest("unowned"),BsonLite.EMPTY_DOCUMENT,BaiyeHost.ACCOUNT,null,null),"unowned untouched");}
  Files.write(Paths.get(args[1]),new org.json.JSONObject(cases).toString(2).getBytes("UTF-8"));System.out.println("PASS actual generic resource negative; original Store exact std.dwr-only delta, repeat, pre/post-rename, typed empty share and callbacks");
 }
}
